SELECT id, layout_id, layout_version_id, assignee_id, title, description, start_x, start_y, end_x, end_y, severity, status, created_at FROM risks
AND assignee_id = #{assigneeId}
AND (title LIKE CONCAT('%', #{query}, '%') OR description LIKE CONCAT('%', #{query}, '%'))
ORDER BY id DESC LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM risks
AND assignee_id = #{assigneeId}
AND (title LIKE CONCAT('%', #{query}, '%') OR description LIKE CONCAT('%', #{query}, '%'))

SELECT id, layout_id, layout_version_id, assignee_id, title, description, start_x, start_y, end_x, end_y, severity, status, created_at FROM risks WHERE layout_id IN
#{layoutId}
ORDER BY layout_id, id

SELECT id, layout_id, layout_version_id, assignee_id, title, description, start_x, start_y, end_x, end_y, severity, status, created_at FROM risks WHERE layout_version_id IN
#{layoutVersionId}
ORDER BY layout_version_id, id

SELECT risk_id, law_serial_number, law_article_number FROM risk_attached_laws WHERE risk_id IN
#{riskId}
